lam=1.5406
def tt(a,c,h,k,l):
    s=(h*h+k*k)/a**2+l*l/c**2
    d=1/np.sqrt(s)
    x=lam/(2*d)
    if x>1: return None
    return 2*np.degrees(np.arcsin(x))
out=[]
for h,k,l in itertools.product(range(0,5),range(0,5),range(0,5)):
